 function rememberEditor(){const form=root.querySelector('[data-case-form=save]');if(!form||!values)return;for(const[group,payload]of Object.entries(values)){const field=form.elements.namedItem(fieldNames[group]);if(field)payload[fieldNames[group]]=field.value;}if(form.elements.caseStatement)editorStatement=form.elements.caseStatement.value;if(form.elements.caseGeometryType)editorGeometry={type:form.elements.caseGeometryType.value,text:form.elements.caseCoordinates.value};}
 function canUpload(){return !details?.origin&&details?.selectedRevision===details?.eventRevision&&typeof authority.uploadCaseDocument==='function'&&authority.permissions?.includes('edit')&&authority.roles?.some(role=>['preparer','reviewer'].includes(role))&&Object.keys(values||{}).some(group=>access.groups[group].update);}
 function renderUpload(){if(!canUpload())return '';const selected=upload?.groups||[],pending=Boolean(upload?.intentBody),ready=upload?.status==='ready';return `<section data-case-source-intake><h4>Add a protected case original</h4><p>Choose one document up to 25 MiB for this case. Its exact file hash is reserved under the selected field permissions before upload. After it is retained, choose it in the source list and seal a reviewed case update to link it.</p><form class="ew-form" data-case-form="upload" data-private-form="true"><label><span>Original case document</span><input type="file" name="caseOriginal" accept=".pdf,.txt,.csv,.html,.htm,.json,.docx,.xlsx" ${privateAttribute}${pending?' disabled':''}></label>${upload?`<p><strong>${h(upload.name)}</strong> · ${(upload.size/1024/1024).toFixed(2)} MiB · ${h(ready?'Retained; choose it in the case source list':upload.status||'Ready for an explicit upload')}</p>`:''}<fieldset><legend>Field permissions for this original</legend>${Object.keys(values||{}).filter(group=>access.groups[group].update).map(group=>checkbox('caseUploadGroup',group,labels[group],selected.includes(group),pending)).join('')}</fieldset><label><span>What this file is for</span><textarea name="caseFilePurpose" minlength="20" maxlength="4000" ${privateAttribute}${pending?' readonly':''}>${h(upload?.purpose||'')}</textarea><small>This preparation note stays in this page. Include the relevant explanation in your reviewed case statement when saving the link.</small></label>${checkbox('caseUploadReviewed','yes','I checked this file, its case and the field permissions for its contents.',false,pending)}<button type="submit"${!upload||ready||pending?' disabled':''}>Reserve protection, upload and retain original</button></form>${pending&&!ready?`<button type="button" data-case-action="retry-upload">Retry this protected original</button>`:''}${upload?.conflict?`<button type="button" data-case-action="review-upload">Review current saved revision</button>${upload.conflict.current?`<form class="ew-form" data-case-form="upload-reconcile" data-private-form="true"><p>Attachment prepared at revision ${upload.expectedRevision}. Current saved engagement: ${h(upload.conflict.current.name)} · ${h(upload.conflict.current.status)} · revision ${upload.conflict.current.revision}.</p>${checkbox('caseAttachmentReviewed','yes','I reviewed the current saved record and choose to add this retained original at its displayed revision.')}<button type="submit">Add original using reviewed revision</button></form>`:''}`:''}${upload?'<button type="button" data-case-action="clear-upload">Clear this upload selection</button>':''}<p class="ew-small">PDF, text, HTML, JSON and Office documents use this flow. Photos and audio use field capture.</p>${groups.every(group=>access.groups[group].read&&access.groups[group].update)?`<a class="ew-link" data-case-field-capture href="/fieldwork?${h(new URLSearchParams({mode:'authenticated',account:scope.accountId,project:scope.projectId,engagement:scope.engagementId,grievanceId:selectedCase}).toString())}">Prepare field capture for this case</a>`:''}</section>`;}
